            inParenthesis = true;
            return this;
        }

        public Builder closeParenthesisAndPlus() {
            number += sideNumber;
            inParenthesis = false;
            sideNumber = 0;
            return this;
        }

        public Builder closeParenthesisAndMinus() {
            number -= sideNumber;
            inParenthesis = false;
            sideNumber = 0;
            return this;
        }

        public Builder closeParenthesisAndMultiply() {
            number *= sideNumber;
            inParenthesis = false;
            sideNumber = 0;
            return this;
        }

        public Builder closeParenthesisAndDivide() {
            number /= sideNumber;
            inParenthesis = false;
            sideNumber = 0;
            return this;
        }

        public Builder format(String format) {
            DecimalFormat formatter = new DecimalFormat(format);
            String num = formatter.format(number);
            number = Double.parseDouble(num);
            return this;
        }

        public Builder format(int decimalPlace) {
            String pattern = "."
                + "#".repeat(decimalPlace);
            DecimalFormat formatter = new DecimalFormat(pattern);
            String num = formatter.format(number);
            number = Double.parseDouble(num);
            return this;
        }

        public MathBuilder build() {
            return new MathBuilder(this);
        }
    }
}

